    "voice_ref": {
     "kind": "visual",
     "uid": "b10"
    }
   },
   {
    "uid": "b11",
    "event_uids": [],
    "text": "听香惊恐尖叫，张十三喝问凶手",
    "purpose": "承载听香与张十三的对话",
    "evidence": "公……公子他……杀……杀人啦……",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d01"
    }
   },
   {
    "uid": "b12",
    "event_uids": [],
    "text": "张十三逼问听香凶手是谁",
    "purpose": "承载张十三的追问",
    "evidence": "凶手是谁，如何刺杀了公子，快说！",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d02"
    }
   },
   {
    "uid": "b13",
    "event_uids": [],
    "text": "听香颤抖着描述刺客从水中跃出刺杀杨旭",
    "purpose": "承载听香的描述",
    "evidence": "不……不知道，那人……那人一下子从水里跳出来，就……就杀了公子，然后又……又跳进水里不见了，奴家……奴家连他是男是女都没看清……",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d03"
    }
   },
   {
    "uid": "b14",
    "event_uids": [],
    "text": "张十三怒喝住嘴",
    "purpose": "承载张十三的怒喝",
    "evidence": "住嘴！",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d04"
    }
   },
   {
    "uid": "b15",
    "event_uids": [],
    "text": "张十三威胁听香这场官司打到官府里休想脱身",
    "purpose": "承载张十三的威胁",
    "evidence": "这场官司打到官府里，你便休想脱身了。",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d05"
    }
   },
   {
    "uid": "b16",
    "event_uids": [],
    "text": "听香哭诉不关自己的事",
    "purpose": "承载听香的哭诉",
    "evidence": "十三郎，真的不关奴家的事啊，奴家当时正在……正在……",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d06"
    }
   },
   {
    "uid": "b17",
    "event_uids": [],
    "text": "张十三厉声威胁听香若不想吃官司便听吩咐",
    "purpose": "承载张十三的威胁",
    "evidence": "你若不想吃官司，便听我吩咐，由我作主，莫要胡乱声张。",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d07"
    }
   },
   {
    "uid": "b18",
    "event_uids": [],
    "text": "听香连声答应听从张十三",
    "purpose": "承载听香的答应",
    "evidence": "是是是，奴家……奴家听你的，都听你的。",
    "source": {},
    "voice_ref": {
     "kind": "dialogue",
     "uid": "d08"
    }
   },
   {
    "uid": "b19",
    "event_uids": [],
    "text": "佃仆赶到岸边询问出了什么事",
    "purpose": "承载佃仆的询问",
